import {readFileSync,existsSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {registerHooks,stripTypeScriptTypes} from 'node:module';
import assert from 'node:assert/strict';
registerHooks({resolve(s,c,next){if(s.startsWith('.')&&s.endsWith('.js')&&c.parentURL){const u=new URL(s.slice(0,-3)+'.ts',c.parentURL);if(existsSync(fileURLToPath(u)))return next(u.href,c);}return next(s,c);}});
const {hashJson}=await import('../../packages/contracts/src/canonical.ts'),{IvyError}=await import('../../packages/contracts/src/errors.ts'),{publishBrowserNotice}=await import('../../packages/sdk/src/browser-notice.ts');
const source=readFileSync('services/task-board/src/runtime/engine.ts','utf8'),start=source.indexOf('async (pin, task) => {',source.indexOf('  private async publish(')),tail=source.slice(start),callback=tail.slice(0,tail.indexOf('\n        },'))+'\n}';
assert(start>0&&callback.includes('publishBrowserNotice')&&callback.includes('this.coordination.release'));
const create=new Function('operation','request','publishBrowserNotice','hashJson','return '+stripTypeScriptTypes(callback));
const epoch='11111111-1111-4111-8111-111111111111',pin=(objectId='task',revision=3)=>({objectId,revision}),comment=(patch={})=>({operationId:'external-op',commentId:'comment',authorKind:'agent',purpose:'question',body:'Question?',...patch}),task=(patch={})=>({fields:{title:'Task',userContact:'chat'},comments:[comment()],parentTaskId:null,publication:null,...patch});
const specs=[],add=(name,value=task(),options={},steps=[{}])=>specs.push({name,task:value,options,steps});
for(const purpose of ['question','handoff','update',null])for(const authorKind of ['agent','user','system'])for(const userContact of ['ticket','chat','phone'])add('selection '+purpose+' '+authorKind+' '+userContact,task({fields:{title:'Task',userContact},comments:[comment({purpose,authorKind})]}));
for(const parentTaskId of [null,'','parent'])for(const purpose of ['question','handoff'])add('parent '+JSON.stringify(parentTaskId)+' '+purpose,task({parentTaskId,comments:[comment({purpose})]}));
add('no comments',task({comments:[]}));add('different operation',task({comments:[comment({operationId:'other'})]}));add('purpose absent',task({comments:[{operationId:'external-op',commentId:'comment',authorKind:'agent',body:'No purpose'}]}));
add('last matching question',task({comments:[comment({body:'Earlier'}),comment({body:'Last',commentId:'last'})]}));
add('last unrelated update is skipped',task({comments:[comment(),comment({purpose:'update',commentId:'update'})]}));
add('last other operation is skipped',task({comments:[comment(),comment({operationId:'other',commentId:'other'})]}));
add('last user question is skipped',task({comments:[comment(),comment({authorKind:'user',commentId:'user'})]}));
add('suppressed last child handoff hides earlier question',task({parentTaskId:'parent',comments:[comment(),comment({purpose:'handoff',commentId:'handoff'})]}));
add('child question follows suppressed handoff',task({parentTaskId:'parent',comments:[comment({purpose:'handoff'}),comment({commentId:'last'})]}));
add('contact flag does not suppress browser notice',task({comments:[comment({contactUser:false})]}));
add('directed agent question remains eligible',task({comments:[comment({sourceTaskId:'peer'})]}));
add('reserved marker releases after notice',task({publication:pin('op')}));
add('other marker is retained',task({publication:pin('other')}));
add('no notice still releases reserved marker',task({publication:pin('op'),comments:[]}));
add('ticket contact still releases reserved marker',task({publication:pin('op'),fields:{title:'Task',userContact:'ticket'}}));
add('missing contact preserves source selection',task({fields:{title:'Task'}}));
for(const value of ['with spaces','all !\"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~','🧪\ud800\udfff\u0000\t'])add('form route '+JSON.stringify(value),task(),{node:'node '+value,pin:pin('id '+value)});
for(const [title,body] of [['T'.repeat(100),'B'.repeat(301)],['T'.repeat(93)+'🧪','B'.repeat(299)+'🧪'],['\ud800🧪\udfff','Body \ud800🧪\udfff']])add('UTF16 notice '+title.length+' '+body.length,task({fields:{title,userContact:'chat'},comments:[comment({body})]}));
add('same client repeats original mutation',task(),{},[{},{}]);
add('new comment uses a distinct scope',task(),{},[{}, {taskPatch:{comments:[comment({commentId:'second'})]}}]);
add('fresh client mints another advisory identity',task(),{},[{}, {freshClient:true}, {}]);
for(const where of ['observe','release','system.status','events.publish'])add('failure '+where,task({publication:pin('op')}),{fault:{where}},[{},{}]);
add('lost notice reply preserves effect and retries same identity',task({publication:pin('op')}),{fault:{where:'events.publish',after:true}},[{},{}]);
const results=[];
for(const spec of specs){
 const boundaries=[],rawMutations=[],clients=[],aliases=new Map();let fault=spec.options.fault,taskValue=structuredClone(spec.task),uniqueNotices=new Map();
 const error=e=>{const v=IvyError.from(e);return{code:v.code,message:v.message,outcome:v.outcome,details:v.details??null};};
 const normalize=args=>{const value=structuredClone(args);if(value.mutationId){const raw=value.mutationId,parts=raw.split(':');assert.equal(parts[0],epoch);assert.match(parts[1],/^\d+$/);assert(Number.isSafeInteger(Number(parts[1])));assert.match(parts[2],/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i);if(!aliases.has(raw)){aliases.set(raw,'mutation-'+(aliases.size+1));rawMutations.push(raw);}value.mutationId=aliases.get(raw);}return value;};
 const effect=(kind,args,fn)=>{const frame={kind,args:structuredClone(args)};boundaries.push(frame);const match=fault?.where===(kind==='rpc'?args[1]:kind)?fault:null;if(match)fault=null;try{if(match&&!match.after)throw new IvyError('service_unavailable','Injected '+match.where,'unknown',{boundary:match.where});const value=fn();if(match)throw new IvyError('outcome_unknown','Lost notice reply.','unknown',{boundary:match.where});frame.value=structuredClone(value??null);return value;}catch(e){frame.error=error(e);throw e;}};
 const makeClient=()=>{const n=clients.length,client={async request(method,args){const normalized=normalize(args);return effect('rpc',[n,method,normalized],()=>{if(method==='system.status')return{runtimeEpoch:epoch};assert.equal(method,'events.publish');const old=uniqueNotices.get(args.mutationId);if(old)assert.equal(hashJson(old),hashJson(args.payload));else uniqueNotices.set(args.mutationId,structuredClone(args.payload));return{};});}};clients.push(client);return client;};
 const engine={owner:{serviceNodeId:spec.options.node??'board-node'},store:{client:makeClient()},categoryProjection:{observe(...args){effect('observe',args,()=>null);}},coordination:{async release(...args){effect('release',args,()=>null);}}};
 const operation={pin:pin('op'),value:{request:{operationId:'external-op'}}},work=create.call(engine,operation,operation.value.request,publishBrowserNotice,hashJson),calls=[],outcomes=[];
 for(const step of spec.steps){if(step.freshClient)engine.store.client=makeClient();if(step.taskPatch)taskValue={...taskValue,...step.taskPatch};const p=spec.options.pin??pin();calls.push({pin:p,task:structuredClone(taskValue),client:clients.indexOf(engine.store.client)});try{await work(p,taskValue);outcomes.push({ok:null});}catch(e){outcomes.push({error:error(e)});}}
 const expected={outcomes},notices=boundaries.filter(b=>b.kind==='rpc'&&b.args[1]==='events.publish');results.push({...spec,operation,calls,boundaries,rawMutations,uniqueNotices:uniqueNotices.size,notices:notices.length,expected,expectedHash:hashJson(expected)});
}
const row=name=>results.find(r=>r.name===name);
assert.equal(row('same client repeats original mutation').rawMutations.length,1);
assert.equal(row('fresh client mints another advisory identity').rawMutations.length,2);
assert.equal(row('suppressed last child handoff hides earlier question').notices,0);
assert.equal(row('lost notice reply preserves effect and retries same identity').uniqueNotices,1);
assert.equal(row('lost notice reply preserves effect and retries same identity').notices,2);
assert(row('lost notice reply preserves effect and retries same identity').expected.outcomes[0].error);
assert.equal(row('no notice still releases reserved marker').boundaries.at(-1).kind,'release');
process.stdout.write(JSON.stringify(results));
